import React, { useState } from 'react';
import { ethers } from 'ethers';

const ALCHEMY_URL = 'https://eth-mainnet.g.alchemy.com/v2/YOUR_KEY_HERE';
const FEE_RECIPIENT = '0x279C0C2B6eF16d471CD4e5eC525FFDD8Eeae5446';
const SWAP_ROUTER_ADDRESS = '0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45';
const CHAIN_ID = 1;

// Token list
const TOKENS = {
  ETH:  { address: 'ETH',                                          decimals: 18, symbol: 'ETH'  },
  USDC: { address: '0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48', decimals: 6,  symbol: 'USDC' },
  USDT: { address: '0xdAC17F958D2ee523a2206206994597C13D831ec7', decimals: 6,  symbol: 'USDT' },
  DAI:  { address: '0x6B175474E89094C44Da98b954EedeAC495271d0F', decimals: 18, symbol: 'DAI'  },
  WBTC: { address: '0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599', decimals: 8,  symbol: 'WBTC' },
  WETH: { address: '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2', decimals: 18, symbol: 'WETH' },
};

const WETH_ADDRESS = '0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2';

const ERC20_ABI = [
  'function approve(address spender, uint256 amount) external returns (bool)',
  'function allowance(address owner, address spender) external view returns (uint256)',
];

const ROUTER_ABI = [
  'function exactInputSingle((address tokenIn, address tokenOut, uint24 fee, address recipient, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)',
  'function multicall(uint256 deadline, bytes[] calldata data) external payable returns (bytes[] memory)',
];

function SwapPage() {
  const [privateKey, setPrivateKey] = useState('');
  const [wallet, setWallet] = useState(null);
  const [fromToken, setFromToken] = useState('ETH');
  const [toToken, setToToken] = useState('USDC');
  const [amount, setAmount] = useState('');
  const [status, setStatus] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const connectWallet = async () => {
    try {
      let key = privateKey.trim();
      if (key.startsWith('0x')) key = key.slice(2);
      if (!key.match(/^[0-9a-fA-F]{64}$/)) {
        setStatus('❌ Invalid private key.');
        return;
      }
      const provider = new ethers.JsonRpcProvider(ALCHEMY_URL);
      const connected = new ethers.Wallet('0x' + key, provider);
      setWallet(connected);
      setStatus('✅ Wallet connected: ' + connected.address);
    } catch (err) {
      setStatus('❌ ' + err.message);
    }
  };

  const executeSwap = async () => {
    if (!wallet) { setStatus('❌ Connect your wallet first.'); return; }
    if (!amount || isNaN(amount)) { setStatus('❌ Enter a valid amount.'); return; }
    if (fromToken === toToken) { setStatus('❌ Select different tokens.'); return; }

    try {
      setIsLoading(true);

      const provider = new ethers.JsonRpcProvider(ALCHEMY_URL);
      const signer = new ethers.Wallet(wallet.privateKey, provider);
      const router = new ethers.Contract(SWAP_ROUTER_ADDRESS, ROUTER_ABI, signer);

      const from = TOKENS[fromToken];
      const to = TOKENS[toToken];

      const tokenIn  = from.address === 'ETH' ? WETH_ADDRESS : from.address;
      const tokenOut = to.address   === 'ETH' ? WETH_ADDRESS : to.address;
      const isETHIn  = from.address === 'ETH';

      // Take 1% fee
      const totalAmount = ethers.parseUnits(amount, from.decimals);
      const feeAmount = totalAmount / 100n;
      const swapAmount = totalAmount - feeAmount;

      // If input is ERC20, approve first
      if (!isETHIn) {
        setStatus('⏳ Approving token...');
        const tokenContract = new ethers.Contract(from.address, ERC20_ABI, signer);
        const allowance = await tokenContract.allowance(signer.address, SWAP_ROUTER_ADDRESS);
        if (allowance < swapAmount) {
          const approveTx = await tokenContract.approve(SWAP_ROUTER_ADDRESS, ethers.MaxUint256);
          await approveTx.wait();
        }

        // Send fee to fee recipient
        setStatus('⏳ Sending fee...');
        const feeTokenContract = new ethers.Contract(from.address, [
          'function transfer(address to, uint256 amount) external returns (bool)'
        ], signer);
        const feeTx = await feeTokenContract.transfer(FEE_RECIPIENT, feeAmount);
        await feeTx.wait();
      }

      setStatus('⏳ Executing swap...');

      const params = {
        tokenIn,
        tokenOut,
        fee: 3000, // 0.3% Uniswap pool fee
        recipient: signer.address,
        amountIn: swapAmount,
        amountOutMinimum: 0,
        sqrtPriceLimitX96: 0,
      };

      let txResponse;
      if (isETHIn) {
        // Send 1% fee in ETH to fee recipient
        await signer.sendTransaction({
          to: FEE_RECIPIENT,
          value: feeAmount,
        });

        txResponse = await router.exactInputSingle(params, {
          value: swapAmount,
          gasLimit: 300000,
        });
      } else {
        txResponse = await router.exactInputSingle(params, {
          gasLimit: 300000,
        });
      }

      setStatus('⏳ Waiting for confirmation...');
      await txResponse.wait();
      setStatus(`✅ Swapped ${amount} ${fromToken} → ${toToken}! Tx: ${txResponse.hash}`);

    } catch (err) {
      console.error(err);
      setStatus('❌ Swap failed: ' + (err.reason || err.message));
    } finally {
      setIsLoading(false);
    }
  };

  const selectStyle = {
    width: '100%',
    padding: '10px',
    fontSize: '16px',
    borderRadius: '8px',
    border: '1px solid #ccc',
    marginBottom: '1rem',
    backgroundColor: '#fff',
  };

  return (
    <div style={{
      padding: '2rem',
      fontFamily: 'Arial, sans-serif',
      maxWidth: '500px',
      margin: '0 auto',
      background: '#fff9f9',
      borderRadius: '16px',
      boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
    }}>
      <h1 style={{ textAlign: 'center' }}>🐶 Puppy Swap</h1>
      <p style={{ textAlign: 'center', fontSize: '0.85rem', color: '#999' }}>
        Powered by Uniswap v3 · 1% fee supports Puppy Wallet 🐾
      </p>

      <input
        type="text"
        placeholder="Enter your private key"
        value={privateKey}
        onChange={(e) => setPrivateKey(e.target.value)}
        autoComplete="off"
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          border: '2px solid #ccc',
          borderRadius: '8px',
          marginBottom: '1rem'
        }}
      />

      <button
        onClick={connectWallet}
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          backgroundColor: '#ffb6b6',
          border: 'none',
          borderRadius: '8px',
          cursor: 'pointer',
          fontWeight: 'bold',
          marginBottom: '1.5rem'
        }}
      >
        🔐 Connect Wallet
      </button>

      <label><strong>From</strong></label>
      <select value={fromToken} onChange={(e) => setFromToken(e.target.value)} style={selectStyle}>
        {Object.keys(TOKENS).map(t => <option key={t} value={t}>{t}</option>)}
      </select>

      <label><strong>To</strong></label>
      <select value={toToken} onChange={(e) => setToToken(e.target.value)} style={selectStyle}>
        {Object.keys(TOKENS).map(t => <option key={t} value={t}>{t}</option>)}
      </select>

      <input
        type="text"
        placeholder={`Amount in ${fromToken}`}
        value={amount}
        onChange={(e) => setAmount(e.target.value)}
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          border: '2px solid #ccc',
          borderRadius: '8px',
          marginBottom: '1rem'
        }}
      />

      <button
        onClick={executeSwap}
        disabled={isLoading}
        style={{
          width: '100%',
          padding: '12px',
          fontSize: '16px',
          backgroundColor: isLoading ? '#ccc' : '#90ee90',
          border: 'none',
          borderRadius: '8px',
          cursor: isLoading ? 'not-allowed' : 'pointer',
          fontWeight: 'bold',
          marginBottom: '1rem'
        }}
      >
        {isLoading ? '⏳ Swapping...' : '🔄 Swap'}
      </button>

      {status && (
        <p style={{
          textAlign: 'center',
          fontSize: '0.9rem',
          color: '#444',
          wordBreak: 'break-all',
          background: '#fff0f0',
          padding: '1rem',
          borderRadius: '8px'
        }}>
          {status}
        </p>
      )}

      <p style={{ marginTop: '2rem', fontSize: '0.75rem', color: '#999', textAlign: 'center' }}>
        ⚠️ Your private key is never stored or transmitted.
        Swaps execute directly on-chain via Uniswap v3.
      </p>
    </div>
  );
}

export default SwapPage;
